static public File allocateFile(File dir, String name) {
    if (dir == null) throw new IllegalArgumentException("Directory must not be null");
    if (name == null) throw new IllegalArgumentException("File name must not be null");
    // Remove query part
    int q = name.indexOf('?');
    if (q > 0) {
        name = name.substring(0, q);
    }
    // Trim whitespace
    name = name.trim();
    if (name.isEmpty()) {
        throw new IllegalArgumentException("File name must not be empty");
    }

    // Normalize base directory path
    Path basePath = dir.toPath().toAbsolutePath().normalize();

    // Resolve the file path
    Path filePath = basePath.resolve(name).normalize();

    // Ensure the resolved path is within the base directory
    if (!filePath.startsWith(basePath)) {
        throw new IllegalArgumentException("Invalid file name: path traversal detected");
    }

    // Determine prefix/suffix for duplicate handling
    String fileName = filePath.getFileName().toString();
    int dot = fileName.lastIndexOf('.');
    String prefix = dot < 0 ? fileName : fileName.substring(0, dot);
    String suffix = dot < 0 ? "" : fileName.substring(dot);
    int index = 2;
    while (Files.exists(filePath)) {
        String newName = prefix + "-" + index++ + suffix;
        filePath = basePath.resolve(newName).normalize();
        // safety check again
        if (!filePath.startsWith(basePath)) {
            throw new IllegalStateException("Generated file name escaped base directory");
        }
    }

    // Ensure parent directories exist
    Files.createDirectories(filePath.getParent());

    return filePath.toFile();
}

