        if (control == -1) {
            throw new IOException("Unexpected end of compressed data");
        }
        if (control == 0) {
            throw new IOException("Invalid control byte 0 encountered in compressed data");
        }
        if (control > 128) {
            int repeatCount = control & 0x7F;
            int value = in.read();
            if (value == -1) {
                throw new IOException("Unexpected end of compressed data while reading repeat value");
            }
            if (repeatCount > total - position) {
                throw new IOException("Repeat count exceeds output buffer size");
            }
            for (int i = 0; i < repeatCount; i++) {
