    int retryCount = 0;

    while (cb.hasRemaining()) {
        CoderResult res = enc.encode(cb, out, false);
        if (res.isUnderflow()) {
            // all input consumed
            break;
        }
        if (res.isOverflow()) {
            // need more space in the output buffer
            int increment = estimateIncrementalEncodingSize(enc, cb.remaining());
            out = ZipEncodingHelper.growBufferBy(out, increment);
            // continue without advancing retryCount
            continue;
        }
        if (res.isUnmappable() || res.isMalformed()) {
            // protect against endless retries
            if (++retryCount > MAX_RETRIES) {
                throw new IllegalStateException("Too many unmappable/malformed characters while encoding");
            }

            // ensure there is enough room for the surrogate representation
            int needed = estimateIncrementalEncodingSize(enc, 6 * res.length());
            if (needed > out.remaining()) {
                // compute extra space required for the remaining characters
                int charCount = 0;
                for (int i = cb.position(); i < cb.limit(); i++) {
                    charCount += !enc.canEncode(cb.get(i)) ? 6 : 1;
                }
                int totalExtra = estimateIncrementalEncodingSize(enc, charCount);
                out = ZipEncodingHelper.growBufferBy(out, totalExtra - out.remaining());
            }

            if (tmp == null) {
                tmp = CharBuffer.allocate(6);
