        } catch (ParserConfigurationException | SAXNotRecognizedException | SAXNotSupportedException ignored) {
            // Feature not supported – continue with the next hardening steps.
        }

        // 2. Disable external general entities.
        try {
            f.setFeature("http://xml.org/sax/features/external-general-entities", false);
        } catch (ParserConfigurationException | SAXNotRecognizedException | SAXNotSupportedException ignored) {
            // Best‑effort hardening; continue even if the parser cannot disable it.
        }

        // 3. Disable external parameter entities.
        try {
            f.setFeature("http://xml.org/sax/features/external-parameter-entities", false);
        } catch (ParserConfigurationException | SAXNotRecognizedException | SAXNotSupportedException ignored) {
