private void expand(ArchiveEntrySupplier supplier, EntryWriter writer, File targetDirectory) throws IOException {
    // Resolve the target directory to a canonical absolute path once
    final Path targetDirCanonical = targetDirectory.getCanonicalFile().toPath();

    ArchiveEntry entry = supplier.getNextReadableEntry();
    while (entry != null) {
        String entryName = entry.getName();

        // Reject absolute paths or empty names
        if (entryName == null || entryName.isEmpty()) {
            throw new IOException("Archive entry name is empty");
        }
        if (new File(entryName).isAbsolute()) {
            throw new IOException("Absolute entry name not allowed: " + entryName);
        }

        // Resolve the file that would be created
        File file = new File(targetDirectory, entryName);
        Path fileCanonical = file.getCanonicalFile().toPath();

        // Ensure the resolved path is inside the target directory
        if (!fileCanonical.startsWith(targetDirCanonical)) {
            throw new IOException("Entry '" + entryName + "' would be extracted outside of target directory");
        }

        if (entry.isDirectory()) {
            if (!file.isDirectory() && !file.mkdirs()) {
                throw new IOException("Failed to create directory " + file);
            }
        } else {
            // Ensure parent directory exists
            File parent = file.getParentFile();
            if (parent != null && !parent.isDirectory() && !parent.mkdirs()) {
                throw new IOException("Failed to create directory " + parent);
            }

            // Write the entry data
            try (OutputStream out = Files.newOutputStream(file.toPath())) {
                writer.writeEntryDataTo(entry, out);
            }
        }

        entry = supplier.getNextReadableEntry();
    }
}
