public class ObjectArrayCodec implements ObjectSerializer, ObjectDeserializer {

    /** Whitelisted component classes that are considered safe for deserialization. */
    private static final Set<Class<?>> SAFE_COMPONENT_TYPES = Collections.unmodifiableSet(
            new HashSet<>(Arrays.asList(
                    Boolean.class,
                    Byte.class,
                    Short.class,
                    Integer.class,
                    Long.class,
                    Float.class,
                    Double.class,
                    String.class,
                    java.math.BigDecimal.class,
                    java.math.BigInteger.class,
                    java.util.Date.class,
                    java.sql.Date.class,
                    java.sql.Timestamp.class,
                    byte[].class,
                    char[].class
