     *
     * @param parser    the JSON parser used to read the JSON data
     * @param type      the type of the array to deserialize into
     * @param fieldName the name of the field being deserialized
     * @return the deserialized object array of type T, or {@code null} if the JSON token is {@code NULL}
     */
    @SuppressWarnings({ "unchecked", "rawtypes" })
    public <T> T deserialze(DefaultJSONParser parser, Type type, Object fieldName) {

        final JSONLexer lexer = parser.lexer;

        // 1. Handle explicit JSON null
        if (lexer.token() == JSONToken.NULL) {
            lexer.nextToken(JSONToken.COMMA);
            return null;
