                // Resolve type variable against the parser context
                TypeVariable<?> typeVar = (TypeVariable<?>) componentType;
                Type contextType = parser.getContext().type;

                if (contextType instanceof ParameterizedType) {
                    ParameterizedType pt = (ParameterizedType) contextType;
                    Type raw = pt.getRawType();
                    Type actual = null;

                    if (raw instanceof Class) {
                        TypeVariable<?>[] vars = ((Class<?>) raw).getTypeParameters();
                        for (int i = 0; i < vars.length; ++i) {
                            if (vars[i].getName().equals(typeVar.getName())) {
