            Class<?> arrayClass = (Class<?>) type;
            componentClass = arrayClass.getComponentType();
            componentType = componentClass;
        }

        // -----------------------------------------------------------------
        // 4. Validate the resolved component class against the whitelist
        // -----------------------------------------------------------------
        if (!SAFE_COMPONENT_TYPES.contains(componentClass)) {
            throw new IllegalArgumentException(
                    "Deserialization of array component type '" + componentClass.getName()
                            + "' is not allowed for security reasons.");
        }

        // -----------------------------------------------------------------
        // 5. Parse the JSON array into a JSONArray using the safe component class
        // -----------------------------------------------------------------
        JSONArray array = new JSONArray();
        parser.parseArray(componentClass, array, fieldName);

        // -----------------------------------------------------------------
        // 6. Convert the JSONArray into a native Java array of the component type
        // -----------------------------------------------------------------
        return (T) toObjectArray(parser, componentClass, array);
    }

    // -----------------------------------------------------------------
    // Existing helper methods (unchanged) – they are required for the
    // conversion from JSONArray to a native Java array.
    // -----------------------------------------------------------------
    private static Object toObjectArray(DefaultJSONParser parser, Class<?> componentType, JSONArray array) {
        int size = array.size();
        Object result = java.lang.reflect.Array.newInstance(componentType, size);
